<?php
require_once __DIR__.'/../includes/functions.php';require_role(['admin']);expire_donations($pdo);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='report'){$reportId=filter_var($_POST['report_id']??null,FILTER_VALIDATE_INT);$reportStatus=$_POST['report_status']??'';if($reportId&&in_array($reportStatus,['Reviewed','Resolved','Dismissed'],true)){$q=$pdo->prepare('UPDATE reports SET status=? WHERE id=?');$q->execute([$reportStatus,$reportId]);flash('success','Report status updated.');}else flash('error','Invalid report update.');redirect('donations.php');}$id=filter_var($_POST['donation_id']??null,FILTER_VALIDATE_INT);if($id){$q=$pdo->prepare("UPDATE food_donations SET status=IF(status='Deactivated','Active','Deactivated') WHERE id=? AND status IN ('Active','Partially Collected','Deactivated')");$q->execute([$id]);flash('success','Listing moderation status updated.');}redirect('donations.php');}
$where='1=1';$params=[];$category=$_GET['category']??'';$status=$_GET['status']??'';$locality=trim($_GET['locality']??'');$from=$_GET['from']??'';$to=$_GET['to']??'';if(in_array($category,['Vegetarian','Non-Vegetarian','Vegan','Bakery','Fruits','Other'],true)){$where.=' AND d.category=?';$params[]=$category;}if(in_array($status,['Active','Partially Collected','Fully Collected','Expired','Cancelled','Deactivated'],true)){$where.=' AND d.status=?';$params[]=$status;}if($locality!==''){$where.=' AND d.locality LIKE ?';$params[]='%'.$locality.'%';}if($from&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where.=' AND DATE(d.created_at)>=?';$params[]=$from;}if($to&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where.=' AND DATE(d.created_at)<=?';$params[]=$to;}$stmt=$pdo->prepare("SELECT d.*,u.name donor_name FROM food_donations d JOIN users u ON u.id=d.donor_id WHERE $where ORDER BY d.created_at DESC");$stmt->execute($params);$donations=$stmt->fetchAll();$reports=$pdo->query("SELECT r.*,u.name reporter,d.food_name FROM reports r JOIN users u ON u.id=r.reporter_id JOIN food_donations d ON d.id=r.donation_id ORDER BY r.created_at DESC LIMIT 40")->fetchAll();$page_title='Manage listings | SharePlate';require __DIR__.'/../includes/header.php';?>
<section class="page-hero compact"><div class="container"><p class="eyebrow">Administration</p><h1>Donations & reports</h1><div class="admin-nav"><a href="dashboard.php">Overview</a><a href="users.php">Users</a><a href="donations.php">Donations & reports</a><a href="requests.php">Requests</a></div></div></section><section class="container section"><form class="filter-bar" method="get"><input type="date" aria-label="From date" name="from" value="<?=e($from)?>"><input type="date" aria-label="To date" name="to" value="<?=e($to)?>"><select name="category"><option value="">All categories</option><?php foreach(['Vegetarian','Non-Vegetarian','Vegan','Bakery','Fruits','Other'] as $c):?><option <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach(['Active','Partially Collected','Fully Collected','Expired','Cancelled','Deactivated'] as $s):?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><input name="locality" placeholder="Locality" value="<?=e($locality)?>"><button class="button">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Listing</th><th>Donor</th><th>Category</th><th>Locality</th><th>Expiry</th><th>Status</th><th>Moderate</th></tr></thead><tbody><?php foreach($donations as $d):?><tr><td><a href="../food-details.php?id=<?=$d['id']?>"><?=e($d['food_name'])?></a></td><td><?=e($d['donor_name'])?></td><td><?=e($d['category'])?></td><td><?=e($d['locality'])?></td><td><?=e(format_datetime($d['expiry_at']))?></td><td><?=e($d['status'])?></td><td><?php if(in_array($d['status'],['Active','Partially Collected','Deactivated'],true)):?><form method="post" data-confirm="Toggle this listing's availability?"><?=csrf_field()?><input type="hidden" name="donation_id" value="<?=$d['id']?>"><button class="link-button"><?=$d['status']==='Deactivated'?'Reactivate':'Deactivate'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><h2 class="section-subheading">Reported content</h2><?php if($reports):?><div class="table-wrap"><table><thead><tr><th>Listing</th><th>Reporter</th><th>Reason</th><th>Description</th><th>Status</th><th>Created</th><th>Moderation</th></tr></thead><tbody><?php foreach($reports as $r):?><tr><td><?=e($r['food_name'])?></td><td><?=e($r['reporter'])?></td><td><?=e($r['reason'])?></td><td><?=e($r['description'])?></td><td><?=e($r['status'])?></td><td><?=e(format_datetime($r['created_at']))?></td><td><form method="post" class="report-status-form"><?=csrf_field()?><input type="hidden" name="action" value="report"><input type="hidden" name="report_id" value="<?=$r['id']?>"><select name="report_status" aria-label="Report status"><option value="Reviewed">Reviewed</option><option value="Resolved">Resolved</option><option value="Dismissed">Dismissed</option></select><button class="link-button">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No reports have been filed.</p><?php endif;?></section><?php require __DIR__.'/../includes/footer.php';?>